/**
 * Feuilles de style importees pour leur effet (`import './globals.css'`).
 *
 * Next 14 ne declare que les CSS Modules (`*.module.css`). Depuis TypeScript 6,
 * `noUncheckedSideEffectImports` est actif par defaut : sans cette
 * declaration, l'editeur signale l'import de app/layout.tsx (TS2882).
 */
declare module '*.css'
